-- ===========================================================================
-- DUMMY SEEDER UNTUK KAS PCC 2026 (SUPABASE POSTGRESQL)
-- Total 50 Transaksi (32 Pemasukan + 18 Pengeluaran)
-- Terdistribusi dinamis selama 6 bulan terakhir (CURRENT_DATE - INTERVAL)
-- Cocok untuk mengetes grafik bar chart dashboard, statistik saldo, & badge pending
-- ===========================================================================

-- 1. ROLES

-- 2. JABATANS

-- 3. PENGATURAN
VALUES (1, 10000, '2026-03-01 00:00:00', '2027-03-01 00:00:00')
ON CONFLICT (id) DO UPDATE SET target_kas_per_bulan = EXCLUDED.target_kas_per_bulan;

-- 4. ANGGOTAS (70 Anggota Asli PCC)

-- 5. USERS (Default Password: 'password')

-- 6. MODEL HAS ROLES

-- 7. PEMASUKAN KAS (32 Transaksi terbagi rata 6 bulan)

-- 8. PENGELUARAN KAS (18 Transaksi terbagi rata 6 bulan)

-- 9. RESTART SEQUENCES (Biar kalau buat transaksi baru lewat UI tidak error ID collision)
SELECT setval(pg_get_serial_sequence('roles', 'id'), coalesce(max(id), 1)) FROM roles;
SELECT setval(pg_get_serial_sequence('jabatans', 'id'), coalesce(max(id), 1)) FROM jabatans;
SELECT setval(pg_get_serial_sequence('anggotas', 'id'), coalesce(max(id), 1)) FROM anggotas;
SELECT setval(pg_get_serial_sequence('users', 'id'), coalesce(max(id), 1)) FROM users;
SELECT setval(pg_get_serial_sequence('pemasukan_kas', 'id'), coalesce(max(id), 1)) FROM pemasukan_kas;
SELECT setval(pg_get_serial_sequence('detail_pemasukan_kas', 'id'), coalesce(max(id), 1)) FROM detail_pemasukan_kas;
SELECT setval(pg_get_serial_sequence('pengeluaran_kas', 'id'), coalesce(max(id), 1)) FROM pengeluaran_kas;
SELECT setval(pg_get_serial_sequence('detail_pengeluaran_kas', 'id'), coalesce(max(id), 1)) FROM detail_pengeluaran_kas;
SELECT setval(pg_get_serial_sequence('bukti_nota_pengeluaran', 'id'), coalesce(max(id), 1)) FROM bukti_nota_pengeluaran;

-- 10. STORAGE BUCKETS (Jika tabel storage.buckets tersedia di Supabase)
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'storage' AND table_name = 'buckets') THEN
    VALUES ('bukti_pemasukan_kas', 'bukti_pemasukan_kas', true), ('bukti_pengeluaran_kas', 'bukti_pengeluaran_kas', true)
    ON CONFLICT (id) DO NOTHING;
  END IF;
END $$;
